begin;
create table platform.notification_external_outbox(id uuid primary key default extensions.gen_random_uuid(),event_type text not null check(event_type~'^[a-z][a-z0-9_.-]{2,80}$'),module_key text not null check(module_key in('conference','reservations','warehouse','platform')),resource_type text not null check(resource_type~'^[a-z][a-z0-9_.-]{2,80}$'),resource_id text not null,scope_type text not null check(scope_type~'^[a-z][a-z0-9_.-]{2,80}$'),scope_id text not null,destination_kind text not null check(destination_kind in('phone','email')),destination text not null check(char_length(destination) between 3 and 320),channels text[] not null check(channels<@array['whatsapp','sms','email']::text[] and cardinality(channels)>0),payload jsonb not null check(jsonb_typeof(payload)='object'),dedupe_key text not null unique check(char_length(dedupe_key) between 1 and 240),created_at timestamptz not null default statement_timestamp());
alter table platform.notification_external_outbox enable row level security;alter table platform.notification_external_outbox force row level security;revoke all on platform.notification_external_outbox from public,anon,authenticated,service_role;
create or replace function platform_private.stage_public_registration_decision_external_notification() returns trigger language plpgsql security definer set search_path='' as $$begin if new.state in('approved','rejected','waitlisted') and new.state is distinct from old.state then insert into platform.notification_external_outbox(event_type,module_key,resource_type,resource_id,scope_type,scope_id,destination_kind,destination,channels,payload,dedupe_key)values('public_registration.decision','reservations','public_registration_request',new.request_reference,'event',new.event_id::text,'phone',new.submitted_phone,array['whatsapp','sms']::text[],jsonb_build_object('requestReference',new.request_reference,'state',new.state,'decisionReason',new.decision_reason,'decidedAt',new.decided_at),'public-registration-decision:'||new.id::text||':'||new.revision::text)on conflict(dedupe_key) do nothing;end if;return new;end$$;
revoke all on function platform_private.stage_public_registration_decision_external_notification() from public,anon,authenticated,service_role;
create trigger public_registration_decision_external_notification after update of state on reservations.public_registration_requests for each row execute function platform_private.stage_public_registration_decision_external_notification();
commit;